create extension if not exists pgcrypto;

create table if not exists public.posts (id uuid primary key default gen_random_uuid(), author_id uuid not null references auth.users(id) on delete cascade, body text not null check (char_length(trim(body)) between 1 and 500), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.comments (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, author_id uuid not null references auth.users(id) on delete cascade, body text not null check (char_length(trim(body)) between 1 and 180), created_at timestamptz not null default now());
create table if not exists public.post_likes (post_id uuid not null references public.posts(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), primary key (post_id,user_id));
create table if not exists public.follows (follower_id uuid not null references auth.users(id) on delete cascade, followed_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), primary key (follower_id,followed_id), constraint follows_not_self check (follower_id <> followed_id));
create table if not exists public.daily_moods (user_id uuid not null references auth.users(id) on delete cascade, mood_date date not null, mood text not null check (mood in ('bright','steady','tender','low')), updated_at timestamptz not null default now(), primary key (user_id,mood_date));
create table if not exists public.conversations (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.conversation_participants (conversation_id uuid not null references public.conversations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, primary key (conversation_id,user_id));
create table if not exists public.messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, sender_id uuid not null references auth.users(id) on delete cascade, body text not null check (char_length(trim(body)) between 1 and 600), created_at timestamptz not null default now());
create table if not exists public.face_reveal_consents (conversation_id uuid not null references public.conversations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, consented_at timestamptz not null default now(), primary key (conversation_id,user_id));

create index if not exists posts_created_idx on public.posts(created_at desc);
create index if not exists comments_post_idx on public.comments(post_id,created_at);
create index if not exists messages_conversation_idx on public.messages(conversation_id,created_at);

do $$ declare t text; begin foreach t in array array['posts','comments','post_likes','follows','daily_moods','conversations','conversation_participants','messages','face_reveal_consents'] loop execute format('alter table public.%I enable row level security',t); execute format('alter table public.%I force row level security',t); end loop; end $$;

create policy "Authenticated members read posts" on public.posts for select to authenticated using (true);
create policy "Members create own posts" on public.posts for insert to authenticated with check (auth.uid()=author_id);
create policy "Members update own posts" on public.posts for update to authenticated using (auth.uid()=author_id) with check (auth.uid()=author_id);
create policy "Members delete own posts" on public.posts for delete to authenticated using (auth.uid()=author_id);
create policy "Authenticated members read comments" on public.comments for select to authenticated using (true);
create policy "Members create own comments" on public.comments for insert to authenticated with check (auth.uid()=author_id);
create policy "Members delete own comments" on public.comments for delete to authenticated using (auth.uid()=author_id);
create policy "Authenticated members read likes" on public.post_likes for select to authenticated using (true);
create policy "Members create own likes" on public.post_likes for insert to authenticated with check (auth.uid()=user_id);
create policy "Members delete own likes" on public.post_likes for delete to authenticated using (auth.uid()=user_id);
create policy "Authenticated members read follows" on public.follows for select to authenticated using (true);
create policy "Members manage own follows" on public.follows for all to authenticated using (auth.uid()=follower_id) with check (auth.uid()=follower_id);
create policy "Members manage own moods" on public.daily_moods for all to authenticated using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "Participants read conversations" on public.conversations for select to authenticated using (exists(select 1 from public.conversation_participants cp where cp.conversation_id=id and cp.user_id=auth.uid()));
create policy "Participants read membership" on public.conversation_participants for select to authenticated using (user_id=auth.uid() or exists(select 1 from public.conversation_participants own where own.conversation_id=conversation_id and own.user_id=auth.uid()));
create policy "Participants read messages" on public.messages for select to authenticated using (exists(select 1 from public.conversation_participants cp where cp.conversation_id=messages.conversation_id and cp.user_id=auth.uid()));
create policy "Participants send messages" on public.messages for insert to authenticated with check (auth.uid()=sender_id and exists(select 1 from public.conversation_participants cp where cp.conversation_id=messages.conversation_id and cp.user_id=auth.uid()));
create policy "Members read own reveal consents" on public.face_reveal_consents for select to authenticated using (user_id=auth.uid());
create policy "Members manage own reveal consents" on public.face_reveal_consents for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());

create or replace function public.toggle_post_like(p_post_id uuid) returns boolean language plpgsql security invoker set search_path=public as $$ begin if exists(select 1 from public.post_likes where post_id=p_post_id and user_id=auth.uid()) then delete from public.post_likes where post_id=p_post_id and user_id=auth.uid(); return false; end if; insert into public.post_likes(post_id,user_id) values(p_post_id,auth.uid()) on conflict do nothing; return true; end; $$;
create or replace function public.toggle_follow(p_followed_id uuid) returns boolean language plpgsql security invoker set search_path=public as $$ begin if p_followed_id=auth.uid() then raise exception 'cannot_follow_self'; end if; if exists(select 1 from public.follows where follower_id=auth.uid() and followed_id=p_followed_id) then delete from public.follows where follower_id=auth.uid() and followed_id=p_followed_id; return false; end if; insert into public.follows(follower_id,followed_id) values(auth.uid(),p_followed_id) on conflict do nothing; return true; end; $$;
create or replace function public.get_home_feed(p_limit integer default 30) returns table(post_id uuid,author_id uuid,display_name text,handle text,body text,created_at timestamptz,like_count bigint,comment_count bigint,liked_by_me boolean,following boolean) language sql stable security definer set search_path=public as $$ select p.id,p.author_id,pr.display_name,pr.handle,p.body,p.created_at,(select count(*) from public.post_likes l where l.post_id=p.id),(select count(*) from public.comments c where c.post_id=p.id),exists(select 1 from public.post_likes l where l.post_id=p.id and l.user_id=auth.uid()),exists(select 1 from public.follows f where f.follower_id=auth.uid() and f.followed_id=p.author_id) from public.posts p join public.profiles pr on pr.user_id=p.author_id order by p.created_at desc limit p_limit; $$;
create or replace function public.get_or_create_conversation(p_other_user uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare cid uuid; begin if auth.uid() is null or p_other_user=auth.uid() then raise exception 'invalid_participant'; end if; select cp1.conversation_id into cid from public.conversation_participants cp1 join public.conversation_participants cp2 on cp2.conversation_id=cp1.conversation_id where cp1.user_id=auth.uid() and cp2.user_id=p_other_user limit 1; if cid is not null then return cid; end if; insert into public.conversations default values returning id into cid; insert into public.conversation_participants values(cid,auth.uid()),(cid,p_other_user); return cid; end; $$;
create or replace function public.list_my_conversations() returns table(conversation_id uuid,other_user_id uuid,display_name text,handle text,last_message text,last_message_at timestamptz) language sql security definer set search_path=public as $$ select c.id,other.user_id,p.display_name,p.handle,lm.body,lm.created_at from public.conversations c join public.conversation_participants own on own.conversation_id=c.id and own.user_id=auth.uid() join public.conversation_participants other on other.conversation_id=c.id and other.user_id<>auth.uid() join public.profiles p on p.user_id=other.user_id left join lateral(select m.body,m.created_at from public.messages m where m.conversation_id=c.id order by m.created_at desc limit 1) lm on true order by coalesce(lm.created_at,c.created_at) desc; $$;

revoke execute on function public.toggle_post_like(uuid), public.toggle_follow(uuid), public.get_home_feed(integer), public.get_or_create_conversation(uuid), public.list_my_conversations() from public,anon;
grant execute on function public.toggle_post_like(uuid), public.toggle_follow(uuid), public.get_home_feed(integer), public.get_or_create_conversation(uuid), public.list_my_conversations() to authenticated;
